      color: var(--danger);
      font-size: 1.35rem;
    }

    .dialog-body h2 {
      margin: 0 0 10px;
      font-size: 1.45rem;
    }

    .dialog-body p {
      margin-bottom: 22px;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
    }

    .secondary {
      padding: 12px 16px;
      background: rgba(30, 41, 59, 0.92);
      color: #e2e8f0;
      border: 1px solid rgba(148, 163, 184, 0.18);
    }

    .danger {
      padding: 12px 16px;
      background: var(--danger-strong);
      color: white;
    }

    .danger:hover {
      background: #dc2626;
    }

    .status {
      margin-top: 16px;
      min-height: 1.5em;
      color: #bfdbfe;
      font-size: 0.95rem;
    }

    @media (max-width: 640px) {
      .content,
      .actions,
      .dialog-body {
        padding-left: 18px;
        padding-right: 18px;
      }

      .dialog-actions {
        flex-direction: column-reverse;
      }

