      --bg: #0b1020;
      --panel: rgba(17, 24, 39, 0.88);
      --panel-strong: #111827;
      --line: rgba(148, 163, 184, 0.18);
      --text: #e5eefb;
      --muted: #94a3b8;
      --accent: #60a5fa;
      --danger: #f87171;
      --danger-strong: #ef4444;
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(96, 165, 250, 0.16), transparent 32%),
        linear-gradient(180deg, #0f172a, #020617 72%);
      color: var(--text);
    }

    .page {
      width: min(100%, 920px);
    }

    .preview-card {
      background: var(--panel);
      border: 1px solid var(--line);
      border-radius: 24px;
      overflow: hidden;
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .image-frame {
      position: relative;
      aspect-ratio: 16 / 10;
      background:
        linear-gradient(180deg, rgba(15, 23, 42, 0.15), rgba(15, 23, 42, 0.65)),
        url("https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80")
          center / cover no-repeat;
    }

    .image-badge {
      position: absolute;
      top: 18px;
      left: 18px;
      padding: 8px 12px;
      border-radius: 999px;
      background: rgba(15, 23, 42, 0.75);
      border: 1px solid rgba(148, 163, 184, 0.2);
      color: #dbeafe;
      font-size: 0.82rem;
      letter-spacing: 0.02em;
    }

    .content {
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 24px;
      padding: 24px;
    }

    .copy {
      max-width: 520px;
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      line-height: 1.1;
    }

    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .meta {
      display: grid;
      gap: 8px;
      min-width: 180px;
      align-content: start;
      padding: 18px;
      border-radius: 18px;
      background: rgba(15, 23, 42, 0.72);
      border: 1px solid var(--line);
    }

    .meta strong {
      font-size: 1.1rem;
      color: #f8fafc;
    }

    .actions {
      padding: 0 24px 24px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 14px;
      font: inherit;
      cursor: pointer;
      transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease, opacity 140ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(96, 165, 250, 0.5);
      outline-offset: 3px;
    }

    .trigger {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      min-width: 160px;
      padding: 14px 18px;
      background: rgba(239, 68, 68, 0.16);
      color: #fee2e2;
      border: 1px solid rgba(248, 113, 113, 0.25);
    }

    .trigger:hover {
      background: rgba(239, 68, 68, 0.22);
    }

    dialog {
      width: min(100% - 32px, 420px);
      padding: 0;
      border: 1px solid rgba(148, 163, 184, 0.18);
      border-radius: 22px;
      background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(15, 23, 42, 0.98));
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 6, 23, 0.72);
      backdrop-filter: blur(5px);
    }

    .dialog-body {
      padding: 24px;
    }

    .dialog-icon {
      width: 48px;
      height: 48px;
      display: grid;
      place-items: center;
      border-radius: 14px;
      margin-bottom: 18px;
      background: rgba(239, 68, 68, 0.14);
      color: var(--danger);
      font-size: 1.35rem;
    }

    .dialog-body h2 {
      margin: 0 0 10px;
      font-size: 1.45rem;
    }

    .dialog-body p {
      margin-bottom: 22px;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
    }

    .secondary {
      padding: 12px 16px;
      background: rgba(30, 41, 59, 0.92);
      color: #e2e8f0;
      border: 1px solid rgba(148, 163, 184, 0.18);
    }

    .danger {
      padding: 12px 16px;
      background: var(--danger-strong);
      color: white;
    }

    .danger:hover {
      background: #dc2626;
    }

    .status {
      margin-top: 16px;
      min-height: 1.5em;
      color: #bfdbfe;
      font-size: 0.95rem;
    }

    @media (max-width: 640px) {
      .content,
      .actions,
      .dialog-body {
        padding-left: 18px;
        padding-right: 18px;
      }

      .dialog-actions {
        flex-direction: column-reverse;
      }

      .dialog-actions button,
      .trigger {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="page">
    <section class="preview-card" aria-label="Image preview">
      <div class="image-frame">
        <div class="image-badge">Landscape photo</div>
      </div>

      <div class="content">
        <div class="copy">
          <h1>Evening Coastline</h1>
          <p>
            A saved image from your library. Use the delete action below if you want to remove it permanently.
          </p>
        </div>

        <aside class="meta" aria-label="Image details">
          <span>Resolution</span>
          <strong>4032 x 2520</strong>
          <span>Added to library</span>
          <strong>April 4, 2026</strong>
        </aside>
      </div>

      <div class="actions">
        <button type="button" class="trigger" aria-haspopup="dialog" aria-controls="delete-dialog">
          Delete image
        </button>
        <div class="status" id="status" aria-live="polite"></div>
      </div>
    </section>
  </main>

  <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <div class="dialog-body">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 id="dialog-title">Delete this image?</h2>
      <p id="dialog-description">
        This will remove the image from your library. This action cannot be undone.
      </p>
      <div class="dialog-actions">
        <button type="button" class="secondary" data-close>Cancel</button>
        <button type="button" class="danger" id="confirm-delete">Delete</button>
      </div>
    </div>
  </dialog>

  <script>
    const dialog = document.getElementById("delete-dialog");
    const openButton = document.querySelector(".trigger");
    const closeButton = dialog.querySelector("[data-close]");
    const confirmButton = document.getElementById("confirm-delete");
    const status = document.getElementById("status");

    openButton.addEventListener("click", () => {
      dialog.showModal();
    });

    closeButton.addEventListener("click", () => {
      dialog.close();
    });

    dialog.addEventListener("click", (event) => {
      const bounds = dialog.getBoundingClientRect();
      const clickedOutside =
        event.clientX < bounds.left ||
        event.clientX > bounds.right ||
        event.clientY < bounds.top ||
        event.clientY > bounds.bottom;

      if (clickedOutside) {
        dialog.close();
      }
    });

    confirmButton.addEventListener("click", () => {
      status.textContent = "Image deleted from your library.";
      dialog.close();
      openButton.disabled = true;
      openButton.textContent = "Image deleted";
      openButton.style.opacity = "0.65";
    });
  </script>
</body>
</html>
